syntax:
useLayoutEffect(() => {
  // كود يعمل قبل رسم المتصفح
}, [dependencies]);

example:
function Tooltip() {
  const ref = useRef(null);
  const [top, setTop] = useState(0);

  useLayoutEffect(() => {
    const { height } = ref.current.getBoundingClientRect();
    setTop(-height - 8); // نصحّح الموضع قبل أن يرى المستخدم أي وميض
  }, []);

  return <div ref={ref} style={{ position: "absolute", top }}>تلميح</div>;
}

function ProductList({ products, query }) {
  const filtered = useMemo(
    () => products.filter((p) => p.name.includes(query)),
    [products, query]
  );

  return <ul>{filtered.map((p) => <li key={p.id}>{p.name}</li>)}</ul>;
}

const ProductRow = React.memo(function ProductRow({ product, onDelete }) {
  return <li>{product.name} <button onClick={() => onDelete(product.id)}>حذف</button></li>;
});

function ProductList({ products }) {
  const handleDelete = useCallback((id) => {
    console.log("حذف المنتج", id);
  }, []);

  return products.map((p) => <ProductRow key={p.id} product={p} onDelete={handleDelete} />);
}

function TabContainer() {
  const [tab, setTab] = useState("about");
  const [isPending, startTransition] = useTransition();

  function selectTab(next) {
    startTransition(() => setTab(next));
  }

  return (
    <>
      <button onClick={() => selectTab("posts")}>المقالات</button>
      {isPending && <span>...جارٍ التحميل</span>}
    </>
  );
}

function SearchPage() {
  const [query, setQuery] = useState("");
  const deferredQuery = useDeferredValue(query);

  return (
    <>
      <input value={query} onChange={(e) => setQuery(e.target.value)} />
      <SearchResults query={deferredQuery} />
    </>
  );
}

function PasswordField() {
  const hintId = useId();
  return (
    <>
      <label>
        كلمة المرور
        <input type="password" aria-describedby={hintId} />
      </label>
      <p id={hintId}>يجب أن تحتوي 8 خانات على الأقل</p>
    </>
  );
}

