const [state, formAction, isPending] = useActionState(action, initialState, permalink?);

async function action(previousState, formData) {
  // ...
  return newState;
}

example:
async function submitName(previousState, formData) {
  const name = formData.get("name");
  if (!name) return { error: "الاسم مطلوب" };
  await saveName(name);
  return { error: null };
}

function NameForm() {
  const [state, formAction, isPending] = useActionState(submitName, { error: null });
  return (
    <form action={formAction}>
      <input name="name" />
      {state.error && <p>{state.error}</p>}
      <button disabled={isPending}>{isPending ? "..." : "حفظ"}</button>
    </form>
  );
}
